         B := B + 4;
      end if;
      pragma Assert (Is_Power (Y) and Y < 2 ** 4 and X = Shift_Left (Y, B) and B <= 60);
      if (Y and 2#11#) = 0 then
         Y := Shift_Right (Y, 2);
         B := B + 2;
      end if;
      pragma Assert (Is_Power (Y) and Y < 2 ** 2 and X = Shift_Left (Y, B) and B <= 62);
      if (Y and 1) = 0 then
         Y := Shift_Right (Y, 1);
         B := B + 1;
      end if;
      pragma Assert (Y = 1 and X = Shift_Left (Y, B));
      return B;
   end Log2;

