      pragma Assert
        (for all B in Bit =>
           Table (Shift_Right (Shift_Left (1, B) * Magic, 58)) = B);
      pragma Assert (X = Shift_Left (1, Log2 (X)));
      return Table (Shift_Right (X * Magic, 58));
   end Ctz;
end Ctz_Test;
